// ============ YOUR SITES ============
// url:        the page to check
// expectText: text that must appear on the page (catches "200 OK but broken"); '' to skip
// slowMs:     a response slower than this is reported as slow in the daily report
const SITES = [
  { url: 'https://example.com', expectText: 'Example Domain', slowMs: 3000 },
];
// ====================================

const isTrue = v => v === true || v === 'true' || v === 1;
const incidents = $('Load Incident Log Data').all().map(i => i.json).filter(r => r.url);
const checks = $('Load Recent Checks Data').all().map(i => i.json).filter(r => r.url);

// Last confirmed state per URL (from the incident log)
const lastIncident = {};
incidents.sort((a, b) => new Date(a.changed_at) - new Date(b.changed_at))
  .forEach(r => { lastIncident[r.url] = r; });
// Result of the previous check per URL (for the 2-failures rule)
const lastCheck = {};
checks.sort((a, b) => new Date(a.checked_at) - new Date(b.checked_at))
  .forEach(r => { lastCheck[r.url] = r; });

return SITES.map(s => ({ json: {
  url: s.url,
  expect_text: s.expectText || '',
  slow_ms: Number(s.slowMs) || 3000,
  state: lastIncident[s.url] ? lastIncident[s.url].status : 'up',
  state_since: lastIncident[s.url] ? lastIncident[s.url].changed_at : '',
  prev_check_ok: lastCheck[s.url] ? isTrue(lastCheck[s.url].ok) : true,
} }));

// Checks every site: status code, response time and expected text.
// A failed check is retried once after 5 seconds before it counts as failed.
const helpers = this.helpers;
const TIMEOUT_MS = 10000;
const RETRY_WAIT_MS = 5000;

async function probe(site) {
  const started = Date.now();
  try {
    const res = await helpers.httpRequest({
      url: site.url, method: 'GET', timeout: TIMEOUT_MS,
      returnFullResponse: true, ignoreHttpStatusErrors: true, json: false,
    });
    const ms = Date.now() - started;
    const code = Number(res.statusCode);
    const body = typeof res.body === 'string' ? res.body : JSON.stringify(res.body || '');
    if (!(code >= 200 && code < 400)) return { ok: false, status_code: code, response_ms: ms, reason: 'HTTP ' + code };
    if (site.expect_text && !body.includes(site.expect_text))
      return { ok: false, status_code: code, response_ms: ms, reason: 'Expected text missing: "' + site.expect_text + '"' };
    return { ok: true, status_code: code, response_ms: ms, reason: 'OK' };
  } catch (e) {
    const ms = Date.now() - started;
    const msg = String((e && (e.code || e.message)) || e);
    const reason = /timeout|ETIMEDOUT|ECONNABORTED/i.test(msg) ? 'Timeout after ' + TIMEOUT_MS / 1000 + 's'
      : /ENOTFOUND|EAI_AGAIN/i.test(msg) ? 'Host not found (DNS)'
      : /ECONNREFUSED/i.test(msg) ? 'Connection refused'
      : /CERT|SSL|TLS/i.test(msg) ? 'TLS/certificate error'
      : 'No response: ' + msg.slice(0, 120);
    return { ok: false, status_code: 0, response_ms: ms, reason };
  }
}

const out = [];
for (const item of $input.all()) {
  const site = item.json;
  let r = await probe(site);
  let retried = false;
  if (!r.ok) {
    await new Promise(res => setTimeout(res, RETRY_WAIT_MS));
    r = await probe(site);
    retried = true;
  }
  out.push({ json: { ...site, ...r, retried, checked_at: new Date().toISOString() } });
}
return out;

// Decides what happened for each site.
// DOWN      = this check AND the previous check failed (2 in a row, so no false alarms)
// RECOVERED = the site was down and this check passed (includes the downtime)
return $input.all().map(item => {
  const c = item.json;
  let event = '';
  let downtime_minutes = 0;
  if (c.state === 'up' && !c.ok && !c.prev_check_ok) event = 'down';
  if (c.state === 'down' && c.ok) {
    event = 'recovered';
    downtime_minutes = c.state_since
      ? Math.max(0, Math.round((new Date(c.checked_at) - new Date(c.state_since)) / 60000)) : 0;
  }
  const slow = c.ok && c.response_ms > c.slow_ms;
  return { json: { ...c, event, downtime_minutes, slow } };
});

