// Builds the daily report: last 24 hours compared with the 24 hours before.
const isTrue = v => v === true || v === 'true' || v === 1;
const now = Date.now(), H24 = 24 * 3600 * 1000;
const rows = $('Load 48h Check Data').all().map(i => i.json).filter(r => r.url);
const incidents = $('Load Recent Incidents Data').all().map(i => i.json).filter(r => r.url);
const esc = s => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));

function stats(list) {
  const n = list.length;
  const okRows = list.filter(r => isTrue(r.ok));
  const ms = okRows.map(r => Number(r.response_ms)).filter(Number.isFinite).sort((a, b) => a - b);
  return {
    n, fails: n - okRows.length,
    uptime: n ? (okRows.length / n) * 100 : null,
    avg: ms.length ? Math.round(ms.reduce((a, b) => a + b, 0) / ms.length) : null,
    p95: ms.length ? ms[Math.min(ms.length - 1, Math.ceil(ms.length * 0.95) - 1)] : null,
  };
}
const fmt = v => (v === null ? 'n/a' : v.toFixed(2) + '%');
const urls = [...new Set(rows.map(r => r.url))].sort();
const lines = [];
let worst = null;
const tr = [];
for (const url of urls) {
  const mine = rows.filter(r => r.url === url);
  const t = Date.parse.bind(Date);
  const today = stats(mine.filter(r => now - t(r.checked_at) <= H24));
  const prev = stats(mine.filter(r => now - t(r.checked_at) > H24));
  const delta = today.uptime !== null && prev.uptime !== null ? (today.uptime - prev.uptime) : null;
  const inc = incidents.filter(r => r.url === url && now - t(r.changed_at) <= H24)
    .sort((a, b) => t(a.changed_at) - t(b.changed_at))
    .map(r => r.status === 'down' ? 'down ' + r.changed_at.slice(11, 16) + ' UTC (' + r.reason + ')'
      : 'recovered ' + r.changed_at.slice(11, 16) + ' UTC after ' + r.downtime_minutes + ' min');
  if (today.uptime !== null && (worst === null || today.uptime < worst.uptime)) worst = { url, uptime: today.uptime };
  lines.push(url + '\n  uptime ' + fmt(today.uptime) + (delta === null ? '' : ' (' + (delta >= 0 ? '+' : '') + delta.toFixed(2) + ' vs previous day)') +
    ' | avg ' + (today.avg ?? 'n/a') + ' ms | p95 ' + (today.p95 ?? 'n/a') + ' ms | failed checks ' + today.fails + ' of ' + today.n +
    (inc.length ? '\n  incidents: ' + inc.join('; ') : ''));
  tr.push('<tr><td>' + esc(url) + '</td><td>' + fmt(today.uptime) + '</td><td>' + (delta === null ? '' : (delta >= 0 ? '+' : '') + delta.toFixed(2)) +
    '</td><td>' + (today.avg ?? 'n/a') + '</td><td>' + (today.p95 ?? 'n/a') + '</td><td>' + today.fails + ' / ' + today.n + '</td><td>' + esc(inc.join('; ') || '-') + '</td></tr>');
}
const allUp = urls.length > 0 && urls.every(u => stats(rows.filter(r => r.url === u && now - Date.parse(r.checked_at) <= H24)).fails === 0);
const subject = urls.length === 0
  ? 'Uptime report: NO CHECKS in the last 24h - is the monitor active?'
  : (allUp ? 'Uptime report: all ' + urls.length + ' sites 100%' : 'Uptime report: lowest ' + fmt(worst.uptime) + ' (' + worst.url + ')');
const text = urls.length === 0
  ? 'No checks were recorded in the last 24 hours. Check that the monitor workflow is active.'
  : 'DAILY UPTIME REPORT (last 24h vs previous 24h)\n\n' + lines.join('\n\n');
const html = urls.length === 0 ? '<p>' + esc(text) + '</p>'
  : '<h2 style="font-family:sans-serif">Daily uptime report</h2><p style="font-family:sans-serif">Last 24 hours compared with the 24 hours before.</p>' +
    '<table border="1" cellpadding="6" style="border-collapse:collapse;font-family:sans-serif;font-size:13px">' +
    '<tr><th>URL</th><th>Uptime</th><th>Change</th><th>Avg ms</th><th>p95 ms</th><th>Failed checks</th><th>Incidents</th></tr>' + tr.join('') + '</table>';
return [{ json: { subject, text, html, sites: urls.length } }];
